// ResolveEntireAPIToken mints a bearer for entire-api (the per-cell product
// API). entire-api verifies that the token's audience equals the jurisdiction
// it serves, so audienceOrigin must be the jurisdictional identity-token
// audience the caller derived from the repo's mirror and
// ENTIRE_API_AUDIENCE_TEMPLATE — NOT the entire-api host.
//
// Unlike ResolveDataAPIToken there is no /.well-known discovery (entire-api
// serves none): the audience is supplied explicitly and the token is exchanged
// from the active login context. That context's core must therefore be the one
// that signs tokens for this jurisdiction — true for single-core deployments;
// minting at a foreign jurisdiction's core (ENTIRE_CORE_BASE_URL_TEMPLATE) is a
// follow-up.
//
// Callers honouring --insecure-http-auth must call EnableInsecureHTTP first, as
// the data-API path does.
func ResolveEntireAPIToken(ctx context.Context, audienceOrigin string) (string, error) {
	c, ok, err := activeContext()
	if err != nil {
		return "", err
	}
	if !ok {
		return "", &reauthError{msg: "not logged in; run `entire login`", sentinel: ErrNotLoggedIn}
	}

	origin := api.OriginOnly(audienceOrigin)
	allowInsecure := insecureHTTPEnabled() || isLoopbackHTTP(c.CoreURL)
	provider, err := NewRefreshingResourceProvider(c, origin, nil, allowInsecure)
	if err != nil {
		return "", err
	}
	return provider(ctx)
}

