		return "", fmt.Errorf("%w %q: cluster advertises no apiUrl (entire-api cell not configured?)", ErrNoCellForJurisdiction, jurisdiction)
	}
	return "", fmt.Errorf("%w %q", ErrNoCellForJurisdiction, jurisdiction)
}

