func (m recapTUIModel) fetch(requestID int) tea.Cmd {
	return func() tea.Msg {
		start, end := m.rangeKey.Bounds(time.Now())
		resp, err := recap.FetchMeRecap(m.ctx, m.client, start, end, m.repo, 0)
