func (m recapTUIModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case recapDataMsg:
		if msg.requestID != m.requestID {
			return m, nil
		}
		m.loading = false
		m.loadErr = nil
		m.resp = msg.resp
		m = m.withViewport()
		return m, nil

	case recapErrMsg:
		if msg.requestID != m.requestID {
			return m, nil
		}
		m.loading = false
		m.loadErr = msg.err
		return m, nil

	case tea.WindowSizeMsg:
		if msg.Width > 0 {
			m.width = msg.Width
		}
		m.height = max(msg.Height, 1)
		m = m.withViewport()
		return m, nil

	case tea.KeyPressMsg:
		if key.Matches(msg, keys.Quit) || key.Matches(msg, keys.Back) {
			return m, tea.Quit
