211	func (m recapTUIModel) View() tea.View {
212		v := tea.View{AltScreen: true}
213		if m.loadErr != nil {
214			v.SetContent(fmt.Sprintf("\n  Failed to load recap: %s\n\n  Press R to retry or q to quit.\n", recapLoadErrorMessage(m.loadErr)))
215			return v
216		}
217		if m.loading && m.resp == nil {
218			v.SetContent("\n  Loading recap...\n\n  Press q to quit.\n")
219			return v
220		}
221		if !m.ready {
222			return v
223		}
