24	const apiMaxResponseBytes = 32 << 20 // 32 MiB cap on a printed response body.
25	
26	type apiFlags struct {
27		to           string
28		method       string
29		rawFields    []string
30		typedFields  []string
31		headers      []string
32		input        string
33		include      bool
34		insecureHTTP bool
35	}
36	
37	func newAPICmd() *cobra.Command {
38		f := &apiFlags{}
39		cmd := &cobra.Command{
40			Use:   "api <path>",
41			Short: "Make an authenticated request to an Entire API and print the response",
42			Long: "Make an authenticated HTTP request to an Entire API and print the JSON response.\n\n" +
43				"The CLI attaches the right bearer token and dials the right host for the\n" +
44				"chosen backend, so you don't have to plumb auth yourself:\n\n" +
45				"  --to core   the control plane (default): orgs, repos, mirrors, clusters, /me\n" +
46				"  --to cell   your home entire-api cell: /me/* activity, repo aggregates\n\n" +
47				"<path> is the full path on that host, e.g. /api/v1/clusters. These\n" +
48				"placeholders are filled from the current repo's origin remote:\n" +
49				"  {owner} {repo}   the GitHub owner / repo\n" +
50				"  {repo_id}        the repo's Entire ULID (from its mirror) — cells key on this\n\n" +
51				"The method is GET unless a field/body is given (then POST); override with -X.",
52			Example: "  entire api /api/v1/clusters\n" +
53				"  entire api --to cell /api/v1/me/activity\n" +
54				"  entire api --to cell \"/api/v1/me/recap?repo={repo_id}\"\n" +
55				"  entire api -X POST /api/v1/projects -f name=demo",
56			Args: cobra.ExactArgs(1),
57			RunE: func(cmd *cobra.Command, args []string) error {
58				return runAPI(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), args[0], f)
59			},
60		}
61		cmd.Flags().StringVar(&f.to, "to", "core", "which backend to call: core or cell")
62		cmd.Flags().StringVarP(&f.method, "method", "X", "", "HTTP method (default GET, or POST when a field/body is given)")
63		cmd.Flags().StringArrayVarP(&f.rawFields, "raw-field", "f", nil, "add a string parameter in key=value format (repeatable)")
64		cmd.Flags().StringArrayVarP(&f.typedFields, "field", "F", nil, "add a typed parameter in key=value format; true/false/null/numbers are converted (repeatable)")
65		cmd.Flags().StringArrayVarP(&f.headers, "header", "H", nil, "add a request header in key:value format (repeatable)")
66		cmd.Flags().StringVar(&f.input, "input", "", "file with the request body (\"-\" for stdin)")
67		cmd.Flags().BoolVarP(&f.include, "include", "i", false, "print the response status line and headers too")
68		addInsecureHTTPAuthFlag(cmd, &f.insecureHTTP)
69		return cmd
70	}
71	
72	func runAPI(ctx context.Context, w, errW io.Writer, rawPath string, f *apiFlags) error {
73		insecure := applyInsecureHTTPAuth(f.insecureHTTP)
