	if needOwnerRepo {
		s = strings.ReplaceAll(s, "{owner}", owner)
		s = strings.ReplaceAll(s, "{repo}", repo)
	}
	if needRepoID {
		id, err := resolveCurrentRepoID(ctx, forge, owner, repo)
