	t.Parallel()

	// Origin-relative paths are allowed.
	for _, ok := range []string{"/api/v1/clusters", "/api/v1/me/recap?repo=01K", "api/v1/x", "/"} {
		if err := validateAPIPath(ok); err != nil {
